/// Tile set lookup by block path (None = render flat).
pub fn lookup(path: &str) -> Option<(u16, u16)> {
    BLOCK_SETS
        .binary_search_by(|e| e.0.cmp(path))
        .ok()
        .map(|i| (BLOCK_SETS[i].1, BLOCK_SETS[i].2))
}
